using Microsoft.EntityFrameworkCore;
using Microsoft.Data.Sqlite;
using var connection = new SqliteConnection("Data Source=:memory:");
connection.Open();
var options = new DbContextOptionsBuilder<School>().UseSqlite(connection).Options;
using var db = new School(options);
db.Database.EnsureCreated();
db.Students.Add(new Student { Name = "An", Score = 8 });
db.SaveChanges();
Console.WriteLine(db.Students.Count(s => s.Score >= 8));
class Student
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public int Score { get; set; }
}
class School(DbContextOptions<School> options) : DbContext(options)
{
    public DbSet<Student> Students => Set<Student>();
}

